// Shared helpers for tests/asr/*.test.js.
//
// No microphone, no network: fixtures are 16 kHz mono WAV clips generated by
// scripts/gen-test-audio.mjs (MiniMax TTS) and committed under fixtures/.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';
import { DEFAULTS, loadConfig } from '../../src/config.js';
import { BARGE_IN_DEFAULTS } from '../../src/voice/asr/barge-in.js';

export const HERE = path.dirname(fileURLToPath(import.meta.url));
export const FIXTURES = path.join(HERE, 'fixtures');
export const MANIFEST_PATH = path.join(FIXTURES, 'manifest.json');

const require = createRequire(import.meta.url);
let cachedSherpa = null;

/** Load sherpa-onnx-node (CommonJS) — only model-dependent tests need it. */
export function requireSherpa() {
  if (!cachedSherpa) cachedSherpa = require('sherpa-onnx-node');
  return cachedSherpa;
}

export function readManifest() {
  if (!fs.existsSync(MANIFEST_PATH)) throw new Error(`missing fixtures manifest: ${MANIFEST_PATH} (run node scripts/gen-test-audio.mjs)`);
  return JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8'));
}

/** Minimal RIFF/WAVE reader: PCM 16-bit mono. Returns {sampleRate, samples: Float32Array}. */
export function readWav(file) {
  const buf = fs.readFileSync(file);
  if (buf.toString('ascii', 0, 4) !== 'RIFF' || buf.toString('ascii', 8, 12) !== 'WAVE') {
    throw new Error(`not a RIFF/WAVE file: ${file}`);
  }
  let offset = 12;
  let fmt = null;
  let data = null;
  while (offset + 8 <= buf.length) {
    const id = buf.toString('ascii', offset, offset + 4);
    const size = buf.readUInt32LE(offset + 4);
    const body = offset + 8;
    if (id === 'fmt ') {
      fmt = {
        format: buf.readUInt16LE(body),
        channels: buf.readUInt16LE(body + 2),
        sampleRate: buf.readUInt32LE(body + 4),
        bitsPerSample: buf.readUInt16LE(body + 14),
      };
    } else if (id === 'data') {
      data = buf.subarray(body, body + size);
    }
    offset = body + size + (size % 2);
  }
  if (!fmt) throw new Error(`no fmt chunk: ${file}`);
  if (!data) throw new Error(`no data chunk: ${file}`);
  if (fmt.format !== 1 || fmt.bitsPerSample !== 16) throw new Error(`unsupported wav encoding in ${file}: ${JSON.stringify(fmt)}`);
  const n = Math.floor(data.length / 2 / fmt.channels);
  const samples = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const s = data.readInt16LE(i * 2 * fmt.channels); // mono only: first channel
    samples[i] = s / 32768;
  }
  return { sampleRate: fmt.sampleRate, samples };
}

export function loadFixture(name) {
  const manifest = readManifest();
  const entry = manifest.find((m) => m.name === name);
  if (!entry) throw new Error(`unknown fixture: ${name}`);
  const wav = readWav(path.join(FIXTURES, entry.file));
  return { ...entry, ...wav };
}

export function silence(ms) {
  return new Float32Array(Math.round((16000 * ms) / 1000));
}

export function concat(parts) {
  const total = parts.reduce((n, p) => n + p.length, 0);
  const out = new Float32Array(total);
  let off = 0;
  for (const p of parts) { out.set(p, off); off += p.length; }
  return out;
}

/** config for tests: real paths, but no portal/hotkey side effects by default. */
export function makeConfig(overrides = {}) {
  const config = loadConfig();
  const asr = { ...DEFAULTS.asr, ...(config.asr ?? {}) };
  // Tests never touch the user's portal/mixer and use the immediate-capture
  // behaviour (wakeCaptureFallbackMs is a daemon-side ack option).
  // wakeGiveUpMs shortened for test speed (production default is 5000; the
  // dedicated give-up tests override it explicitly).
  config.asr = {
    ...asr,
    hotkey: '',
    wakeCaptureFallbackMs: 0,
    wakeGiveUpMs: 1500,
    // deterministic tests: always start from the module's measured barge-in
    // defaults (the real user config may have bargeIn.enabled=false from the GUI
    // and src/config.js may still carry an older minRms/echoFactor)
    bargeIn: { ...BARGE_IN_DEFAULTS },
    ...(overrides.asr ?? {}),
  };
  return config;
}

export function modelsAvailable() {
  const config = makeConfig();
  const root = config.paths.root;
  const dir = (p) => path.resolve(root, p);
  const has = (d, re) => {
    if (!fs.existsSync(d)) return false;
    return fs.readdirSync(d).some((f) => re.test(f)) && fs.existsSync(path.join(d, 'tokens.txt'));
  };
  return (
    has(dir(config.asr.kwsModelDir), /^encoder.*\.onnx$/) &&
    fs.existsSync(path.join(dir(config.asr.kwsModelDir), 'tokens.txt')) &&
    (has(dir(config.asr.streamingModelDir), /^encoder.*\.onnx$/) ||
      (fs.existsSync(path.join(dir(config.asr.offlineModelDir), 'tokens.txt')) &&
        fs.readdirSync(dir(config.asr.offlineModelDir)).some((f) => /^model.*\.onnx$/.test(f))))
  );
}

export function skipMessage(t) {
  t.skip('语音模型未安装：先运行 ./scripts/fetch-models.sh');
}

/** Tiny event recorder with promise waiting — used to observe ASR callbacks. */
export function recorder() {
  const events = [];
  const waiters = new Set();
  const push = (ev) => {
    events.push(ev);
    for (const w of [...waiters]) {
      if (!w.pred(ev)) continue;
      waiters.delete(w);
      clearTimeout(w.timer);
      w.resolve(ev);
    }
  };
  return {
    events,
    push,
    /** Wait until a matching event arrives (or reject on timeout). */
    waitFor(pred, timeoutMs = 5000, label = 'event') {
      const existing = events.find(pred);
      if (existing) return Promise.resolve(existing);
      return new Promise((resolve, reject) => {
        const w = { pred, resolve };
        w.timer = setTimeout(() => { waiters.delete(w); reject(new Error(`timeout waiting for ${label} (${timeoutMs}ms)`)); }, timeoutMs);
        waiters.add(w);
      });
    },
    ofType(type) {
      return events.filter((e) => e.type === type);
    },
  };
}

/** Wait until predicate is true (polling), or reject. */
export async function waitUntil(pred, timeoutMs = 5000, label = 'condition') {
  const t0 = Date.now();
  while (Date.now() - t0 < timeoutMs) {
    if (pred()) return;
    await new Promise((r) => setTimeout(r, 20));
  }
  throw new Error(`timeout waiting for ${label}`);
}

/** Feed a Float32Array through a createArraySource at full speed. */
export function arraySource(pcm, extra = {}) {
  return ({ onPcm, onError, onFatal }) => {
    let cancelled = false;
    let timer = null;
    let offset = 0;
    const chunk = 1600;
    return {
      async start() {
        const pump = () => {
          if (cancelled) return;
          if (offset >= pcm.length) { extra.onEnd?.(); return; }
          const end = Math.min(offset + chunk, pcm.length);
          onPcm(pcm.subarray(offset, end));
          offset = end;
          if (offset >= pcm.length) { extra.onEnd?.(); return; }
          timer = setImmediate(pump);
        };
        pump();
      },
      async stop() {
        cancelled = true;
        if (timer) clearImmediate(timer);
        void onError; void onFatal;
      },
    };
  };
}
